sys_script_include.script:
var AssignmentEngine = Class.create();
AssignmentEngine.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getAssignmentGroup: function(current) {
        var cat = current.toString();


        var assRule = new GlideRecord('x_1921506_incide_0_assignment_rule_config');
        assRule.addQuery('category', cat);
        assRule.addQuery('active', true);
        assRule.orderByDesc('priority_weight');
        assRule.query();

        if (assRule.next()) {
            return {
                primaryGroup: assRule.getValue('default_group'),
                secondaryGroup: assRule.getValue('backup_group')
            };
        }


    },

    getEligibleAgents: function(groupSysId, category, priority) {

        var eligibleAgents = [];
        var seenAgents = {};

        // Validate input
        if (!groupSysId || !category || !priority) {
            gs.warn('AssignmentEngine: Missing group, category, or priority.');
            return eligibleAgents;
        }

        // Critical / P1 incidents require Expert proficiency
        var expertOnly = (priority == '1' || priority == 'critical' ||
            priority == 'Critical' || priority == 'P1');

        // Get agents who have the required category skill
        var skillGR = new GlideRecord('x_1921506_incide_0_agent_skill');
        skillGR.addQuery('category', category);
        skillGR.addQuery('active', true);


        if (expertOnly) {
            skillGR.addQuery('proficiency', 'expert');
        }

        skillGR.query();

        while (skillGR.next()) {

            var agentSysId = skillGR.getValue('agent');

            if (!agentSysId || seenAgents[agentSysId]) {
                continue;
            }
            var memberGR = new GlideRecord('sys_user_grmember');
            memberGR.addQuery('user', agentSysId);
            memberGR.addQuery('group', groupSysId);
            // memberGR.setLimit(1);
            memberGR.query();

            if (!memberGR.next()) {
                continue;
            }
            var availabilityGR = new GlideRecord('x_1921506_incide_0_agent_availability');
            availabilityGR.addQuery('agent', agentSysId);
            availabilityGR.addQuery('status', 'available');
            availabilityGR.setLimit(1);
            availabilityGR.query();

            if (!availabilityGR.next()) {
                continue;
            }

            var timezone = availabilityGR.getDisplayValue('time_zone');
            var currentTime = new GlideDateTime();
            var convertedDateTime = new GlideScheduleDateTime(currentTime).convertTimeZone('UTC', timezone);
            var localTime = String(convertedDateTime).split(' ').pop();
            var shiftStart = availabilityGR.getDisplayValue('shift_start');
            var shiftEnd = availabilityGR.getDisplayValue('shift_end');


            if (!shiftStart || !shiftEnd) {
                continue;
            }

            if (shiftStart <= localTime && localTime < shiftEnd) {
                seenAgents[agentSysId] = true;
                eligibleAgents.push(agentSysId);
            }
        }
        gs.info(eligibleAgents);
        return eligibleAgents;



    },

    backup: function(groupSysId, category, priority) {

        var eligibleAgents = [];
        var seenAgents = {};

        // Validate input
        if (!groupSysId || !category || !priority) {
            gs.warn('AssignmentEngine: Missing group, category, or priority.');
            return eligibleAgents;
        }
        var expertOnly = (priority == '1' || priority == 'critical' ||
            priority == 'Critical' || priority == 'P1');

        // Get agents who have the required category skill
        var skillGR = new GlideRecord('x_1921506_incide_0_agent_skill');
        skillGR.addQuery('category', category);
        skillGR.addQuery('active', true);


        if (expertOnly) {
            skillGR.addQuery('proficiency', 'expert');
        }

        skillGR.query();

        while (skillGR.next()) {

            var agentSysId = skillGR.getValue('agent');

            if (!agentSysId || seenAgents[agentSysId]) {
                continue;
            }
            var memberGR = new GlideRecord('sys_user_grmember');
            memberGR.addQuery('user', agentSysId);
            memberGR.addQuery('group', groupSysId);
            // memberGR.setLimit(1);
            memberGR.query();

            if (!memberGR.next()) {
                continue;
            }
            var availabilityGR = new GlideRecord('x_1921506_incide_0_agent_availability');
            availabilityGR.addQuery('agent', agentSysId);
            availabilityGR.addQuery('status', 'available');
            availabilityGR.setLimit(1);
            availabilityGR.query();

            if (!availabilityGR.next()) {
                continue;
            }

            var timezone = availabilityGR.getDisplayValue('time_zone');
            var currentTime = new GlideDateTime();
            var convertedDateTime = new GlideScheduleDateTime(currentTime).convertTimeZone('UTC', timezone);
            var localTime = String(convertedDateTime).split(' ').pop();
            var shiftStart = availabilityGR.getDisplayValue('shift_start');
            var shiftEnd = availabilityGR.getDisplayValue('shift_end');


            if (!shiftStart || !shiftEnd) {
                continue;
            }

            if (shiftStart <= localTime && localTime < shiftEnd) {
                seenAgents[agentSysId] = true;
                eligibleAgents.push(agentSysId);
            }



        }
        gs.info(eligibleAgents + ' return from back up');
        return eligibleAgents;



    },

    findEligibleAgentsWithFallback: function(category, subcategory, priority) {

        var result = {
            success: false,
            groupSysId: '',
            eligibleAgent: [],
            fallbackUsed: false,
            reason: ''
        };

        // STEP 1: Get the primary/default group
        var primary = this.getAssignmentGroup(category);
        var primaryGroup = primary.primaryGroup;


        if (!primaryGroup) {
            result.reason = 'NO_ASSIGNMENT_RULE';
            return result;
        }

        // STEP 2: Check eligibility in the primary group
        var eligibleAgents = this.getEligibleAgents(
            primaryGroup,
            category,
            priority
        );
        gs.info(eligibleAgents + 'elegible agents');
        // If agents are available, no fallback is required
        if (eligibleAgents.length > 0) {
            result.success = true;
            result.groupSysId = primaryGroup;
            for (var i = 0; i < eligibleAgents.length; i++) {
                result.eligibleAgent.push(eligibleAgents[i]);
            }

            result.reason = 'PRIMARY_GROUP_MATCH';
            return result;
        }

        // STEP 3: Find the backup group from the matching rule
        // Use your actual assignment-rule table name.
        var ruleGR = new GlideRecord('x_1921506_incide_0_assignment_rule_config');

        ruleGR.addQuery('category', category);
        ruleGR.addQuery('active', true);


        // if (subcategory) {
        //     ruleGR.addQuery('subcategory', subcategory);
        // }

        ruleGR.orderByDesc('priority_weight');
        ruleGR.query();
        gs.info('hi');
        var backupGroup = '';

        if (ruleGR.next()) {
            gs.info('hi');
            backupGroup = ruleGR.getValue('backup_group');

            gs.info(backupGroup + 'backgroup');
        }

        // STEP 4: Ensure the backup group is configured
        if (!backupGroup || backupGroup == primaryGroup) {
            result.reason = 'NO_USABLE_BACKUP_GROUP';
            return result;
        }

        // STEP 5: Check eligibility in the backup group
        // Your existing method checks membership in THIS group.
        // eligibleAgents = this.backup(backupGroup, category, priority);
         eligibleAgents = this.getEligibleAgents(backupGroup, category, priority);

        if (eligibleAgents.length > 0) {
            result.success = true;
            result.groupSysId = backupGroup;
            for (var j = 0; j < eligibleAgents.length; j++) {
                result.eligibleAgent.push(eligibleAgents[j]);
            }
            result.fallbackUsed = true;
            result.reason = 'BACKUP_GROUP_MATCH';
            return result;
        }

        // STEP 6: Neither group has an eligible agent
        result.reason =
            'NO_ELIGIBLE_AGENTS_IN_DEFAULT_OR_BACKUP_GROUP';

        return result;
    },

    getAgentOpenLoad: function(agentSysId) {

        if (!agentSysId) {
            return 0;
        }

        var agg = new GlideAggregate('incident');

        // Find incidents assigned to this agent
        agg.addQuery('assigned_to', agentSysId);

        // Exclude Resolved and Closed incidents
        agg.addQuery('state', 'NOT IN', '6,7');

        // Count matching incidents
        agg.addAggregate('COUNT');
        agg.query();

        if (agg.next()) {
            return parseInt(agg.getAggregate('COUNT'), 10) || 0;
        }

        return 0;
    },

    selectBestAgent: function(eligibleAgents, priority) {

        var selectedAgent = '';
        var lowestLoad = 999999;

        // Loop through eligible agents
        for (var i = 0; i < eligibleAgents.length; i++) {

            var agentSysId = eligibleAgents[i];

            // Step 1: Get the agent's availability record
            var availabilityGR = new GlideRecord('x_1921506_incide_0_agent_availability');

            availabilityGR.addQuery('agent', agentSysId);
            availabilityGR.addQuery('status', 'available');
            availabilityGR.setLimit(1);
            availabilityGR.query();

            if (!availabilityGR.next()) {
                continue;
            }

            // Step 2: Get maximum concurrent incidents
            var maxLoad = parseInt(
                availabilityGR.getValue('max_concurrent_incident'), 10);

            // if (isNaN(maxLoad) || maxLoad < 0) {
            //     continue;
            // }

            // Step 3: Count the agent's open incidents
            var openLoad = this.getAgentOpenLoad(agentSysId);

            // Step 4: Skip agents who reached capacity
            if (openLoad >= maxLoad) {
                continue;
            }


            // Step 5: Choose the agent with the lowest workload
            if (openLoad < lowestLoad) {
                lowestLoad = openLoad;
                selectedAgent = agentSysId;
                gs.info('CURRENT BEST: ' + selectedAgent +
                    ' | Load: ' + lowestLoad);

            }
        }
        gs.info('FINAL SELECTED AGENT: ' + selectedAgent);

        return selectedAgent;
    },

    logAssignment: function(incidentSysId, groupSysId, agentSysId, reason, type) {

        // Validate mandatory inputs
        if (!incidentSysId) {
            gs.warn('AssignmentEngine: Incident sys_id is missing.');
            return;
        }

        // Create an assignment log record
        var logGR = new GlideRecord('x_1921506_incide_0_assignment_log');
        logGR.initialize();

        // Reference to the incident
        logGR.setValue('incident', incidentSysId);

        // Reference to the assignment group
        if (groupSysId) {
            logGR.setValue('assignment_group', groupSysId);
        }

        // Reference to the assigned agent
        if (agentSysId) {
            logGR.setValue('assignent_agent', agentSysId);
        }

        // Assignment type choice value
        logGR.setValue('assignment_type', type || 'initial');

        // Human-readable reason
        logGR.setValue('reason', reason || 'No reason provided');

        // Assignment timestamp
        logGR.setValue('time_stamp', new GlideDateTime());

        // Insert the record
        var logSysId = logGR.insert();

        if (logSysId) {
            gs.info('AssignmentEngine: Assignment log created. Incident: ' +
                incidentSysId + ', Log: ' + logSysId);
        } else {
            gs.error('AssignmentEngine: Failed to create assignment log for incident ' +
                incidentSysId);
        }
    },


    reassignAgentIncidents: function(agentSysId, reason) {

        var inc = new GlideRecord('incident');
        inc.addQuery('assigned_to', agentSysId);
        inc.addQuery('active', true);
        inc.query();

        while (inc.next()) {

            // Get the incident's current assignment group
            var primaryGroup = inc.getValue('assignment_group');
            var category = inc.getValue('category');
            var priority = inc.getValue('priority');

            // Find eligible agents using your existing method
            var eligibleAgents = this.findEligibleAgentsWithFallback(category, " ", priority);
            var sys = eligibleAgents.eligibleAgent;
            gs.info(sys + ' after finding agent');

            // Do not reassign to the unavailable agent
            var availableAgents = [];

            for (var i = 0; i < sys.length; i++) {
                if (sys[i] != agentSysId) {
                    availableAgents.push(sys[i]);
                }
            }

            // No eligible replacement agent
            if (availableAgents.length == 0) {
                gs.warn(
                    'No replacement agent found for incident ' +
                    inc.getValue('number')
                );
                continue;
            }

            // Select replacement using your existing load-balancing logic
            var newAgent = this.selectBestAgent(availableAgents, priority);

            if (!newAgent || newAgent == agentSysId) {
                continue;
            }

            // Update the incident
            inc.setValue('assigned_to', newAgent);
            inc.setValue('work_notes', 'Re-assignment - Agent OOO. Reason: ' + reason);
            inc.update();
            var sysId = inc.getUniqueValue();
            var log = this.logAssignment(sysId, primaryGroup, newAgent, 'Agent on the leave so new agent is assignned', 'Re-assignment - Agent OOO');
            gs.info('Incident ' + inc.getValue('number') + 'reassigned to agent ' + newAgent);
            return newAgent;


        }
    },

    checkSlaRiskAndReassign: function() {

        var windowStart = new GlideDateTime();
        windowStart.addSeconds(-1860); // 31 minutes

        var inc = new GlideRecord('incident');
        inc.addQuery('state', 'NOT IN', '6,7,8');
        inc.addNotNullQuery('assigned_to');

        var joinMetric = inc.addJoinQuery('metric_instance', 'sys_id', 'id');

        joinMetric.addCondition('start', '<=', windowStart);
        joinMetric.addCondition('definition', '35f0791ac0a808ae008f0a2b1dc1030c');
        joinMetric.addCondition('end', 'ISEMPTY', '');

        var joinSLA = inc.addJoinQuery('task_sla', 'sys_id', 'task');

        joinSLA.addCondition('stage', 'in_progress');
        joinSLA.addCondition('percentage', '>=', 80);

        inc.query();

        var processed = {};

        while (inc.next()) {

            var incidentSysId = inc.getUniqueValue();

            // Avoid processing duplicate join results
            if (processed[incidentSysId]) {
                continue;
            }

            processed[incidentSysId] = true;

            var oldAgent = inc.getValue('assigned_to');
            var oldGroup = inc.getValue('assignment_group');

            var reason = 're_assignment';

            // Reassign this incident only

            this.reassignSingleIncidentForSlaRisk(incidentSysId, reason);
        }
    },

    reassignSingleIncidentForSlaRisk: function(incidentSysId, reason) {

        if (!incidentSysId) {
            gs.error('SLA reassignment failed: Incident sys_id is missing');
            return false;
        }

        // 1. Load the incident
        var inc = new GlideRecord('incident');

        if (!inc.get(incidentSysId)) {
            gs.error('SLA reassignment failed: Incident not found: ' + incidentSysId);
            return false;
        }

        // 2. Get incident details
        var oldAgent = inc.getValue('assigned_to');
        var oldGroup = inc.getValue('assignment_group');
        var category = inc.getValue('category');
        var subcategory = inc.getValue('subcategory');
        var priority = inc.getValue('priority');

        if (!oldAgent) {
            gs.info('SLA reassignment skipped: Incident has no assigned agent');
            return false;
        }

        var eligibleAgents = this.findEligibleAgentsWithFallback(category, " ", priority);
        var sys = eligibleAgents.eligibleAgent;
        gs.info(sys + ' after finding agent');

        // Do not reassign to the unavailable agent
        var availableAgents = [];

        for (var i = 0; i < sys.length; i++) {
            if (sys[i] != oldAgent) {
                availableAgents.push(sys[i]);
            }
        }

        // No eligible replacement agent
        if (availableAgents.length == 0) {
            gs.warn('No replacement agent found for incident ' + inc.getValue('number'));
            return false;
        }

        // Select replacement using your existing load-balancing logic
        var newAgent = this.selectBestAgent(availableAgents, priority);



        if (!newAgent || newAgent == oldAgent) {

            gs.info('SLA reassignment skipped: No suitable replacement for ' + inc.getValue('number'));

            return false;
        }

        // 9. Update the incident assignment
        var oldAgentName = inc.getDisplayValue('assigned_to');

        inc.setValue('assignment_group', selectedGroup);
        inc.setValue('assigned_to', newAgent);

        var updatedSysId = inc.update();
        var sysId = inc.getUniqueValue();

        if (!updatedSysId) {
            gs.error('SLA reassignment failed while updating incident ' + getValue('number'));
            return false;
        }

        var log = this.logAssignment(sysId, oldGroup, newAgent, 'SLA reassignment successful. Incident: ' + inc.getValue('number'), reason);

        gs.info('SLA reassignment successful: ' + inc.getValue('number') + ' reassigned to ' + newAgent);

        return true;
    },






    type: 'AssignmentEngine'
});
